fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Use zip to iterate over both arrays simultaneously
    // Compare each pair with >= and collect into Vec<bool>
    x1.into_iter()
        .zip(x2.into_iter())
        .map(|(a, b)| a >= b)
        .collect()
}